import subprocess
import sys


def test_condefects_0():
    proc = subprocess.run(
        [sys.executable, "buggy.py"],
        input='9 113\n31 21 78 80 49 60 76 78 16\n',
        capture_output=True,
        text=True,
        timeout=10,
    )
    expected = '42\n'
    actual = proc.stdout.strip()
    assert actual == expected.strip(), (
        f"Expected {expected.strip()!r}, got {actual!r}"
    )


